-- Insert 50 sample programming problems of scope PRACTICE
INSERT INTO public.problems (
    id, title, description, input_description, output_description, constraints,
    example_input, example_output, hint, problem_scope, difficulty, is_active,
    created_by, total_testcase, time_limit_ms, memory_limit_kb, is_public, score
) VALUES

(1001, 'Reverse String', 'Write a function that reverses a string. The input string is given as an array of characters.', 'An array of characters.', 'The reversed array of characters.', '1 <= s.length <= 10^5', '["h","e","l","l","o"]', '["o","l","l","e","h"]', 'Use two pointers approach.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1002, 'Fizz Buzz', 'Given an integer n, return a string array answer (1-indexed) where answer[i] is FizzBuzz, Fizz, Buzz, or the number.', 'An integer n.', 'List of string representation.', '1 <= n <= 10^4', '3', '["1","2","Fizz"]', 'Check divisibility by 3 and 5.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1003, 'Palindrome String', 'Given a string s, return true if it is a palindrome, or false otherwise.', 'A string s.', 'boolean value.', '1 <= s.length <= 2 * 10^5', '"racecar"', 'true', 'Use two pointers checking from both ends.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1004, 'Valid Anagram', 'Given two strings s and t, return true if t is an anagram of s, and false otherwise.', 'Two strings s and t.', 'boolean value.', '1 <= s.length, t.length <= 5 * 10^4', '"anagram"\n"nagaram"', 'true', 'Sort the strings or count character frequencies.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1005, 'Single Number', 'Given a non-empty array of integers nums, every element appears twice except for one. Find that single one.', 'An array of integers.', 'The single integer.', '1 <= nums.length <= 3 * 10^4', '[2,2,1]', '1', 'Use XOR operator.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1006, 'Majority Element', 'Given an array nums of size n, return the majority element which appears more than n/2 times.', 'An array of integers.', 'The majority element.', '1 <= nums.length <= 5 * 10^4', '[3,2,3]', '3', 'Boyer-Moore Voting Algorithm.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1007, 'Move Zeroes', 'Given an integer array nums, move all 0''s to the end of it while maintaining the relative order of the non-zero elements.', 'An array of integers.', 'No output (modify in-place or print the array).', '1 <= nums.length <= 10^4', '[0,1,0,3,12]', '[1,3,12,0,0]', 'Use two pointers.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1008, 'Contains Duplicate', 'Given an integer array nums, return true if any value appears at least twice in the array.', 'An array of integers.', 'boolean value.', '1 <= nums.length <= 10^5', '[1,2,3,1]', 'true', 'Use a hash set.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1009, 'Missing Number', 'Given an array nums containing n distinct numbers in the range [0, n], return the only number in the range that is missing.', 'An array of integers.', 'The missing number.', 'n == nums.length, 1 <= n <= 10^4', '[3,0,1]', '2', 'Sum formula: n*(n+1)/2 minus actual sum.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1010, 'Intersection of Two Arrays', 'Given two integer arrays nums1 and nums2, return an array of their intersection.', 'Two arrays of integers.', 'The intersection array.', '1 <= nums1.length, nums2.length <= 1000', '[1,2,2,1]\n[2,2]', '[2]', 'Use a hash set to collect unique values.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1011, 'Power of Two', 'Given an integer n, return true if it is a power of two. Otherwise, return false.', 'An integer n.', 'boolean value.', '-2^31 <= n <= 2^31 - 1', '16', 'true', 'Bitwise check: n > 0 && (n & (n - 1)) == 0.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1012, 'Reverse Vowels of a String', 'Given a string s, reverse only all the vowels in the string and return it.', 'A string s.', 'Modified string.', '1 <= s.length <= 3 * 10^5', '"hello"', '"holle"', 'Use two pointers to find and swap vowels.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1013, 'Is Subsequence', 'Given two strings s and t, return true if s is a subsequence of t, or false otherwise.', 'Two strings s and t.', 'boolean value.', '0 <= s.length <= 100, 0 <= t.length <= 10^4', '"abc"\n"ahbgdc"', 'true', 'Use two pointers.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1014, 'First Unique Character in a String', 'Given a string s, find the first non-repeating character in it and return its index. If it does not exist, return -1.', 'A string s.', 'Index of the character.', '1 <= s.length <= 10^5', '"leetcode"', '0', 'Count frequencies using a hash map or array.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1015, 'Find All Disappeared Numbers', 'Given an array nums of n integers where nums[i] is in the range [1, n], return an array of all the integers in the range [1, n] that do not appear in nums.', 'An array of integers.', 'List of missing numbers.', 'n == nums.length, 1 <= n <= 10^5', '[4,3,2,7,8,2,3,1]', '[5,6]', 'Negate the values at indices corresponding to the elements.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1016, 'Fibonacci Number', 'The Fibonacci numbers, commonly denoted F(n) form a sequence, called the Fibonacci sequence, such that each number is the sum of the two preceding ones.', 'An integer n.', 'The F(n) value.', '0 <= n <= 30', '4', '3', 'Use recursion, memoization, or DP.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1017, 'N-th Tribonacci Number', 'The Tribonacci sequence T(n) is defined as: T(0) = 0, T(1) = 1, T(2) = 1, and T(n+3) = T(n) + T(n+1) + T(n+2). Given n, return T(n).', 'An integer n.', 'The T(n) value.', '0 <= n <= 37', '4', '4', 'Use dynamic programming.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1018, 'Climbing Stairs', 'You are climbing a staircase. It takes n steps to reach the top. Each time you can either climb 1 or 2 steps. In how many distinct ways can you climb to the top?', 'An integer n.', 'Number of distinct ways.', '1 <= n <= 45', '3', '3', 'This is equivalent to the Fibonacci sequence.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1019, 'Min Cost Climbing Stairs', 'You are given an integer array cost where cost[i] is the cost of i-th step on a staircase. Once you pay the cost, you can climb one or two steps.', 'An integer array cost.', 'Minimum cost to reach the top.', '2 <= cost.length <= 1000', '[10,15,20]', '15', 'DP state transition: dp[i] = cost[i] + min(dp[i-1], dp[i-2]).', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1020, 'House Robber', 'You are a professional robber planning to rob houses along a street. Each house has a certain amount of money stashed. Return the maximum money you can rob.', 'An integer array nums.', 'Maximum money.', '1 <= nums.length <= 100', '[1,2,3,1]', '4', 'DP: dp[i] = max(dp[i-1], dp[i-2] + nums[i]).', 'PRACTICE'::public.problem_scope, 'MEDIUM'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1021, 'Best Time to Buy and Sell Stock', 'You are given an array prices where prices[i] is the price of a given stock on the i-th day. You want to maximize your profit.', 'An array of stock prices.', 'Maximum profit.', '1 <= prices.length <= 10^5', '[7,1,5,3,6,4]', '5', 'Track the minimum price seen so far and calculate maximum profit.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1022, 'Maximum Subarray', 'Given an integer array nums, find the subarray with the largest sum, and return its sum.', 'An array of integers.', 'The maximum sum.', '-10^4 <= nums[i] <= 10^4', '[-2,1,-3,4,-1,2,1,-5,4]', '6', 'Kadane''s Algorithm.', 'PRACTICE'::public.problem_scope, 'MEDIUM'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1023, 'Merge Sorted Array', 'You are given two integer arrays nums1 and nums2, sorted in non-decreasing order, and two integers m and n representing their active elements. Merge them.', 'Two arrays nums1, nums2, and lengths m, n.', 'No output (modify nums1 in-place).', 'nums1.length == m + n', '[1,2,3,0,0,0]\n3\n[2,5,6]\n3', '[1,2,2,3,5,6]', 'Fill from the back of nums1.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1024, 'Remove Duplicates from Sorted Array', 'Given an integer array nums sorted in non-decreasing order, remove the duplicates in-place such that each unique element appears only once.', 'A sorted array of integers.', 'Number of unique elements.', '1 <= nums.length <= 3 * 10^4', '[1,1,2]', '2', 'Use two pointers.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1025, 'Remove Element', 'Given an integer array nums and an integer val, remove all occurrences of val in nums in-place. Return the new length.', 'An array of integers and a target value.', 'New length of the array.', '0 <= nums.length <= 100', '[3,2,2,3]\n3', '2', 'Use two pointers.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1026, 'Search Insert Position', 'Given a sorted array of distinct integers and a target value, return the index if the target is found. If not, return the index where it would be.', 'A sorted array of distinct integers and a target value.', 'Insert index.', '1 <= nums.length <= 10^4', '[1,3,5,6]\n5', '2', 'Use binary search.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1027, 'Length of Last Word', 'Given a string s consisting of words and spaces, return the length of the last word in the string.', 'A string s.', 'Length of the last word.', '1 <= s.length <= 10^4', '"Hello World"', '5', 'Trim whitespaces first, then count from end.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1028, 'Plus One', 'You are given a large integer represented as an integer array digits, where each digits[i] is the i-th digit of the integer. Increment the large integer by one.', 'An array of digits.', 'The incremented array of digits.', '1 <= digits.length <= 100', '[1,2,3]', '[1,2,4]', 'Handle carry from right to left.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1029, 'Add Binary', 'Given two binary strings a and b, return their sum as a binary string.', 'Two binary strings.', 'The binary sum string.', '1 <= a.length, b.length <= 10^4', '"11"\n"1"', '"100"', 'Compute sums column by column, keeping track of carry.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1030, 'Sqrt(x)', 'Given a non-negative integer x, return the square root of x rounded down to the nearest integer.', 'A non-negative integer x.', 'The square root.', '0 <= x <= 2^31 - 1', '8', '2', 'Use binary search from 0 to x.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1031, 'Happy Number', 'Write an algorithm to determine if a number n is happy. A happy number is defined by replacing the number by sum of squares of its digits repeatedly.', 'An integer n.', 'boolean value.', '1 <= n <= 2^31 - 1', '19', 'true', 'Use a hash set to detect cycles, or use Floyd Cycle Detection.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1032, 'Excel Sheet Column Title', 'Given an integer columnNumber, return its corresponding column title as it appears in an Excel sheet.', 'An integer columnNumber.', 'The column title string.', '1 <= columnNumber <= 2^31 - 1', '28', '"AB"', 'Convert to base 26 mapping 1-26 to A-Z.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1033, 'Excel Sheet Column Number', 'Given a string columnTitle that represents the column title as appears in an Excel sheet, return its corresponding column number.', 'A string columnTitle.', 'The column number.', '1 <= columnTitle.length <= 7', '"AB"', '28', 'Convert base 26 string to base 10 integer.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1034, 'Power of Three', 'Given an integer n, return true if it is a power of three. Otherwise, return false.', 'An integer n.', 'boolean value.', '-2^31 <= n <= 2^31 - 1', '27', 'true', 'Keep dividing by 3 or use math log.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1035, 'Power of Four', 'Given an integer n, return true if it is a power of four. Otherwise, return false.', 'An integer n.', 'boolean value.', '-2^31 <= n <= 2^31 - 1', '16', 'true', 'Power of 2 check and (n - 1) % 3 == 0.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1036, 'Valid Perfect Square', 'Given a positive integer num, return true if num is a perfect square, else false.', 'An integer num.', 'boolean value.', '1 <= num <= 2^31 - 1', '16', 'true', 'Use binary search or Newton method.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1037, 'Third Maximum Number', 'Given an integer array nums, return the third distinct maximum number in this array. If it does not exist, return the maximum number.', 'An array of integers.', 'The third maximum.', '1 <= nums.length <= 10^4', '[3,2,1]', '1', 'Track the top 3 maximums using distinct variables or a set.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1038, 'Assign Cookies', 'Assume you are an awesome parent and want to give your children some cookies. Each child i has greed factor g[i], cookie size s[j]. Maximize happy children.', 'Greed factor array g and cookie size array s.', 'Max content children.', '1 <= g.length, s.length <= 3 * 10^4', '[1,2,3]\n[1,1]', '1', 'Sort both arrays and use greedy approach.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1039, 'Max Consecutive Ones', 'Given a binary array nums, return the maximum number of consecutive 1s in the array.', 'A binary array nums.', 'Maximum consecutive count.', '1 <= nums.length <= 10^5', '[1,1,0,1,1,1]', '3', 'Loop and keep track of current count and max count.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1040, 'Detect Capital', 'We define the usage of capitals in a word to be right when all letters are capitals, all are lowercase, or only first is capital. Verify word.', 'A string word.', 'boolean value.', '1 <= word.length <= 100', '"USA"', 'true', 'Count capitals or use regex.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1041, 'Base 7', 'Given an integer num, return a string representation of its base 7 representation.', 'An integer num.', 'String of base 7.', '-10^7 <= num <= 10^7', '100', '"202"', 'Perform modulo 7 repeatedly and append to string.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1042, 'Relative Ranks', 'You are given an integer array score of size n, where score[i] is the score of the i-th athlete. Return placement ranks.', 'An array of scores.', 'Ranks as string array.', '1 <= score.length <= 10^4', '[5,4,3,2,1]', '["Gold Medal","Silver Medal","Bronze Medal","4","5"]', 'Sort scores with original index and assign ranks.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1043, 'Perfect Number', 'A perfect number is a positive integer that is equal to the sum of its positive divisors, excluding the number itself. Determine if n is perfect.', 'An integer n.', 'boolean value.', '1 <= n <= 10^8', '28', 'true', 'Find all divisors up to sqrt(n) and sum them.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1044, 'Keyboard Row', 'Given an array of strings words, return the words that can be typed using letters of only one row of American keyboard.', 'An array of strings.', 'Words matching keyboard row.', '1 <= words.length <= 20', '["Hello","Alaska","Dad","Peace"]', '["Alaska","Dad"]', 'Predefine sets for each row and check subset.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1045, 'Find Mode in Array', 'Given an array of integers with duplicates, return all the mode(s) (the most frequently occurred elements).', 'An array of integers.', 'Modes array.', '1 <= nums.length <= 10^4', '[1,2,2,3]', '[2]', 'Count occurrences with a hash map.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1046, 'Minimum Absolute Difference', 'Given an array of distinct integers arr, find all pairs of elements with the minimum absolute difference of any two elements.', 'An array of distinct integers.', 'List of pairs.', '2 <= arr.length <= 10^5', '[4,2,1,3]', '[[1,2],[2,3],[3,4]]', 'Sort array first, then find min diff.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1047, 'Reverse Words in a String III', 'Given a string s, reverse the order of characters in each word within a sentence while still preserving whitespace.', 'A string s.', 'Reversed words sentence.', '1 <= s.length <= 5 * 10^4', '"Let''s take LeetCode contest"', '"s''teL ekat edoCteeL tsetnoc"', 'Split by space, reverse each word, and join back.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1048, 'Array Partition I', 'Given an integer array nums of 2n integers, group these integers into n pairs (a1, b1), (a2, b2) such that the sum of min(ai, bi) is maximized.', 'An array of 2n integers.', 'Maximized sum.', '1 <= n <= 10^4', '[1,4,3,2]', '4', 'Sort array and sum elements at even indices.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1049, 'Valid Palindrome II', 'Given a string s, return true if the s can be palindrome after deleting at most one character from it.', 'A string s.', 'boolean value.', '1 <= s.length <= 10^5', '"aba"', 'true', 'Use two pointers. If mismatch, check if deleting either character forms palindrome.', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00),
(1050, 'Distribute Candies', 'Alice has n candies, where the i-th candy is of type candyType[i]. She wants to eat n/2 candies, maximizing the types. How many types can she eat?', 'An array of candy types.', 'Maximum types.', 'n is even, 2 <= n <= 10^4', '[1,1,2,2,3,3]', '3', 'Result is min(distinct types, n/2).', 'PRACTICE'::public.problem_scope, 'EASY'::public.problem_difficulty, true, 999, 5, 1000, 64000, true, 100.00)
ON CONFLICT (id) DO NOTHING;

-- Synchronize sequence for autoincrement
SELECT setval('public.problems_id_seq', COALESCE((SELECT MAX(id) FROM public.problems), 1));
